import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { z } from 'zod';
import { LEARNING_API_CONTRACT } from './learning';

/*
 * Contract test: the zod response schemas against the API's OpenAPI document.
 * `backend/openapi.json` is generated by drf-spectacular and CI fails when it is stale
 * (see the backend job), so this compares the client with what the server really sends.
 * Regenerate it with:
 *   cd backend && DJANGO_DEBUG=true uv run python manage.py spectacular \
 *     --validate --fail-on-warn --format openapi-json --file openapi.json
 */

type OpenApiSchema = {
  $ref?: string;
  allOf?: OpenApiSchema[];
  type?: string;
  nullable?: boolean;
  enum?: unknown[];
  items?: OpenApiSchema;
  properties?: Record<string, OpenApiSchema>;
  required?: string[];
  additionalProperties?: OpenApiSchema | boolean | Record<string, never>;
};

const doc = JSON.parse(
  readFileSync(join(__dirname, '../../../../../backend/openapi.json'), 'utf8'),
) as { components: { schemas: Record<string, OpenApiSchema> } };
const components = doc.components.schemas;

/** Follows `$ref` and `allOf: [$ref]` (spectacular's nullable reference form). */
function resolve(schema: OpenApiSchema): { schema: OpenApiSchema; nullable: boolean } {
  let nullable = !!schema.nullable;
  let s = schema;
  for (;;) {
    if (s.allOf?.length === 1) s = s.allOf[0];
    else if (s.$ref) s = components[s.$ref.replace('#/components/schemas/', '')];
    else break;
    nullable ||= !!s.nullable;
  }
  return { schema: s, nullable };
}

/** Strips optional / nullable / default wrappers. */
function unwrap(t: z.ZodTypeAny): { inner: z.ZodTypeAny; optional: boolean; nullable: boolean } {
  let optional = false;
  let nullable = false;
  let inner = t;
  for (;;) {
    if (inner instanceof z.ZodOptional) optional = true;
    else if (inner instanceof z.ZodNullable) nullable = true;
    else if (!(inner instanceof z.ZodDefault)) break;
    inner = inner._def.innerType;
  }
  return { inner, optional, nullable };
}

/** Every mismatch between a zod type and an OpenAPI schema, as readable paths. */
function compare(path: string, zod: z.ZodTypeAny, api: OpenApiSchema, problems: string[]): void {
  const { schema } = resolve(api);
  const { inner } = unwrap(zod);
  const kind = schema.enum ? 'enum' : schema.type;
  if (inner instanceof z.ZodObject) {
    if (kind !== 'object') return void problems.push(`${path}: zod object, API ${kind}`);
    const shape = inner.shape as Record<string, z.ZodTypeAny>;
    const props = schema.properties ?? {};
    const required = new Set(schema.required ?? []);
    for (const key of Object.keys(props)) {
      if (!(key in shape)) problems.push(`${path}.${key}: in the API, missing from zod`);
    }
    for (const [key, field] of Object.entries(shape)) {
      const at = `${path}.${key}`;
      if (!(key in props)) {
        problems.push(`${at}: in zod, not sent by the API`);
        continue;
      }
      const f = unwrap(field);
      const r = resolve(props[key]);
      if (required.has(key) && f.optional)
        problems.push(`${at}: API always sends it; zod optional`);
      if (!required.has(key) && !f.optional) problems.push(`${at}: API may omit it; zod requires`);
      if (r.nullable !== f.nullable) {
        problems.push(`${at}: API nullable=${r.nullable}, zod nullable=${f.nullable}`);
      }
      compare(at, field, props[key], problems);
    }
  } else if (inner instanceof z.ZodRecord) {
    const values = schema.additionalProperties;
    if (kind !== 'object' || values === undefined) {
      return void problems.push(`${path}: zod record, API ${kind}`);
    }
    const valueSchema = typeof values === 'object' ? (values as OpenApiSchema) : {};
    if (Object.keys(valueSchema).length)
      compare(`${path}[*]`, inner._def.valueType, valueSchema, problems);
  } else if (inner instanceof z.ZodArray) {
    if (kind !== 'array' || !schema.items)
      return void problems.push(`${path}: zod array, API ${kind}`);
    compare(`${path}[]`, inner.element, schema.items, problems);
  } else if (inner instanceof z.ZodEnum) {
    const ours = [...(inner.options as string[])].sort();
    // A plain string in the API (e.g. question `type`) accepts any of our values.
    if (kind === 'string') return;
    const theirs = [...((schema.enum ?? []) as string[])].filter((v) => v !== '' && v !== null);
    if (kind !== 'enum' || JSON.stringify(ours) !== JSON.stringify(theirs.sort())) {
      problems.push(`${path}: enum ${JSON.stringify(ours)} vs API ${JSON.stringify(theirs)}`);
    }
  } else if (inner instanceof z.ZodNumber) {
    const isInt = inner._def.checks.some((c) => c.kind === 'int');
    if (kind !== (isInt ? 'integer' : 'number')) {
      problems.push(`${path}: zod ${isInt ? 'integer' : 'number'}, API ${kind}`);
    }
  } else if (inner instanceof z.ZodString) {
    if (kind !== 'string') problems.push(`${path}: zod string, API ${kind}`);
  } else if (inner instanceof z.ZodBoolean) {
    if (kind !== 'boolean') problems.push(`${path}: zod boolean, API ${kind}`);
  }
}

describe('learning API contract (zod ↔ OpenAPI)', () => {
  it.each(Object.entries(LEARNING_API_CONTRACT))('%s matches the API', (name, schema) => {
    expect(components[name]).toBeDefined();
    const problems: string[] = [];
    compare(name, schema, components[name], problems);
    expect(problems).toEqual([]);
  });

  it('catches drift: a renamed or retyped field is reported', () => {
    const drifted = LEARNING_API_CONTRACT.Completion.extend({ progressPct: z.string() }).omit({
      firstCompletion: true,
    });
    const problems: string[] = [];
    compare('Completion', drifted, components['Completion'], problems);
    expect(problems).toEqual([
      'Completion.firstCompletion: in the API, missing from zod',
      'Completion.progressPct: zod string, API integer',
    ]);
  });
});
